  `rate` decimal(10,2) NOT NULL,
  `amount` decimal(12,2) GENERATED ALWAYS AS (`qty` * `rate`) STORED,
  `discount_per_qty` decimal(10,2) DEFAULT 0.00,
  `discount_rate` decimal(10,2) GENERATED ALWAYS AS (`rate` * `discount_per_qty` / 100) STORED,
  `discount_total` decimal(12,2) GENERATED ALWAYS AS (`discount_rate` * `qty`) STORED,
  `gst_percent` decimal(5,2) DEFAULT 0.00,
  `gst_amount` decimal(12,2) GENERATED ALWAYS AS ((`qty` * `rate` - `discount_rate` * `qty`) * (`gst_percent` / 100)) STORED,
  `final_amount` decimal(12,2) GENERATED ALWAYS AS (`qty` * `rate` - `discount_rate` * `qty` + `gst_amount`) STORED,
  `status` enum('Active','Cancelled') DEFAULT 'Active',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `unit` varchar(45) DEFAULT NULL,
  `buyer_type` enum('retailer','wholesaler') DEFAULT 'retailer'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

